<script>
  (function() {
    const root = document.documentElement;
    const tok = n => getComputedStyle(root).getPropertyValue(n).trim();

    // state
    let x0 = 1.5;
    let learningRate = 0.1;
    let steps = 5;
    let currentStep = 5; // 初始显示5步

    // DOM refs
    const svg = document.getElementById('stage');
    const tracePath = document.getElementById('tracePath');
    const stepLabel = document.getElementById('stepLabel');
    const x0Input = document.getElementById('x0');
    const x0Val = document.getElementById('x0Val');
    const lrInput = document.getElementById('lr');
    const lrVal = document.getElementById('lrVal');
    const stepsInput = document.getElementById('steps');
    const stepsVal = document.getElementById('stepsVal');
    const currentStepDisplay = document.getElementById('currentStepDisplay');
    const totalStepsDisplay = document.getElementById('totalStepsDisplay');
    const currentXDisplay = document.getElementById('currentXDisplay');
    const currentFDisplay = document.getElementById('currentFDisplay');
    const stepBackBtn = document.getElementById('stepBack');
    const stepForwardBtn = document.getElementById('stepForward');
    const resetBtn = document.getElementById('reset');

    // 坐标映射: x ∈ [-2, 2] → px ∈ [40, 640]; y ∈ [0, 4] → py ∈ [340, 20]
    function xToPx(x) { return 40 + (x + 2) / 4 * 600; }
    function yToPy(y) { return 340 - y / 4 * 320; }
    function f(x) { return x * x; }

    // 计算梯度下降序列
    function computeTrajectory(x0, lr, n) {
      const pts = [];
      let x = x0;
      for (let i = 0; i <= n; i++) {
        pts.push({ x: x, y: f(x), step: i });
        x = x - lr * 2 * x; // 梯度: 2x
      }
      return pts;
    }

    // 单一 update()
    function update() {
      const pts = computeTrajectory(x0, learningRate, steps);
      const showSteps = Math.min(currentStep, steps);
      const visiblePts = pts.slice(0, showSteps + 1);

      // 构建轨迹路径
      let d = '';
      if (visiblePts.length > 0) {
        d = `M ${xToPx(visiblePts[0].x)} ${yToPy(visiblePts[0].y)}`;
        for (let i = 1; i < visiblePts.length; i++) {
          d += ` L ${xToPx(visiblePts[i].x)} ${yToPy(visiblePts[i].y)}`;
        }
      }
      tracePath.setAttribute('d', d);

      // 清除旧点/箭头/标注 (保留 tracePath 和 stepLabel)
      const g = document.getElementById('trajectory');
      // 移除所有子元素除了 tracePath 和 stepLabel
      const children = g.children;
      const toRemove = [];
      for (let i = 0; i < children.length; i++) {
        const el = children[i];
        if (el.id !== 'tracePath' && el.id !== 'stepLabel') {
          toRemove.push(el);
        }
      }
      toRemove.forEach(el => el.remove());

      // 绘制点、箭头、标注
      const accent = tok('--accent');
      const ink = tok('--ink');
      const text2 = tok('--text2');
      const bg = tok('--bg');
      const line = tok('--line');

      for (let i = 0; i < visiblePts.length; i++) {
        const pt = visiblePts[i];
        const cx = xToPx(pt.x);
        const cy = yToPy(pt.y);
        const isFirst = (i === 0);
        const isLast = (i === visiblePts.length - 1);

        // 点
        const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circle.setAttribute('cx', cx);
        circle.setAttribute('cy', cy);
        circle.setAttribute('r', isFirst ? 6 : (isLast ? 6 : 4));
        circle.setAttribute('fill', isFirst ? accent : (isLast ? 'var(--accent)' : 'var(--ink)'));
        circle.setAttribute('stroke', isFirst || isLast ? 'var(--bg)' : 'none');
        circle.setAttribute('stroke-width', '2');
        if (isLast) {
          circle.setAttribute('fill', 'var(--accent)');
          // 星形标记用 path 代替
          const star = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          const s = 8;
          const starD = `M ${cx} ${cy-s} L ${cx+s*0.224} ${cy-s*0.309} L ${cx+s*0.951} ${cy-s*0.309} L ${cx+s*0.363} ${cy+s*0.118} L ${cx+s*0.588} ${cy+s*0.809} L ${cx} ${cy+s*0.382} L ${cx-s*0.588} ${cy+s*0.809} L ${cx-s*0.363} ${cy+s*0.118} L ${cx-s*0.951} ${cy-s*0.309} L ${cx-s*0.224} ${cy-s*0.309} Z`;
          star.setAttribute('d', starD);
          star.setAttribute('fill', 'var(--accent)');
          star.setAttribute('stroke', 'var(--bg)');
          star.setAttribute('stroke-width', '1.5');
          star.setAttribute('class', 'converge-star');
          g.appendChild(star);
          // 隐藏圆点
          circle.setAttribute('r', 0);
        }
        g.appendChild(circle);

        // 箭头 (除最后一点)
        if (i < visiblePts.length - 1) {
          const next = visiblePts[i+1];
          const nx = xToPx(next.x);
          const ny = yToPy(next.y);
          const dx = nx - cx;
          const dy = ny - cy;
          const len = Math.sqrt(dx*dx + dy*dy);
          if (len > 2) {
            const ux = dx / len;
            const uy = dy / len;
            const arrowLen = 10;
            const arrowWidth = 5;
            const midX = cx + dx * 0.5;
            const midY = cy + dy * 0.5;
            const tipX = midX + ux * arrowLen * 0.6;
            const tipY = midY + uy * arrowLen * 0.6;
            const baseX = midX - ux * arrowLen * 0.4;
            const baseY = midY - uy * arrowLen * 0.4;
            const perpX = -uy;
            const perpY = ux;
            const arrow = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
            arrow.setAttribute('points', 
              `${tipX},${tipY} ${baseX + perpX * arrowWidth},${baseY + perpY * arrowWidth} ${baseX - perpX * arrowWidth},${baseY - perpY * arrowWidth}`
            );
            arrow.setAttribute('fill', 'var(--accent)');
            arrow.setAttribute('opacity', '0.6');
            g.appendChild(arrow);
          }
        }

        // 标注 (仅首尾和中间关键点)
        if (isFirst || isLast || i === Math.floor(showSteps/2)) {
          const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          label.setAttribute('x', cx + (isFirst ? -12 : 12));
          label.setAttribute('y', cy - (isFirst ? 14 : 10));
          label.setAttribute('fill', isFirst ? 'var(--accent)' : 'var(--text2)');
          label.setAttribute('font-size', '11');
          label.setAttribute('font-family', 'var(--mono)');
          label.setAttribute('text-anchor', isFirst ? 'end' : 'start');
          let txt = '';
          if (isFirst) txt = `x₀=${pt.x.toFixed(2)}`;
          else if (isLast) txt = `★ x=${pt.x.toFixed(2)}`;
          else txt = `x=${pt.x.toFixed(2)}`;
          label.textContent = txt;
          g.appendChild(label);
        }
      }

      // 更新步数标注
      const lastPt = visiblePts[visiblePts.length-1];
      if (lastPt) {
        stepLabel.textContent = `步 ${showSteps}  x=${lastPt.x.toFixed(4)}  f=${lastPt.y.toFixed(4)}`;
      } else {
        stepLabel.textContent = '';
      }

      // 更新读数
      currentStepDisplay.textContent = showSteps;
      totalStepsDisplay.textContent = steps;
      if (lastPt) {
        currentXDisplay.textContent = lastPt.x.toFixed(4);
        currentFDisplay.textContent = lastPt.y.toFixed(4);
      } else {
        currentXDisplay.textContent = '—';
        currentFDisplay.textContent = '—';
      }
    }

    // 事件绑定
    x0Input.addEventListener('input', function() {
      x0 = parseFloat(this.value);
      x0Val.textContent = x0.toFixed(2);
      currentStep = 0;
      update();
    });
    lrInput.addEventListener('input', function() {
      learningRate = parseFloat(this.value);
      lrVal.textContent = learningRate.toFixed(2);
      currentStep = 0;
      update();
    });
    stepsInput.addEventListener('input', function() {
      steps = parseInt(this.value, 10);
      stepsVal.textContent = steps;
      if (currentStep > steps) currentStep = steps;
      update();
    });
    stepForwardBtn.addEventListener('click', function() {
      if (currentStep < steps) {
        currentStep++;
        update();
      }
    });
    stepBackBtn.addEventListener('click', function() {
      if (currentStep > 0) {
        currentStep--;
        update();
      }
    });
    resetBtn.addEventListener('click', function() {
      currentStep = 0;
      update();
    });

    // 初始渲染
    update();
  })();
</script>
